def transform(grid):
    bg=9
    H=len(grid); W=len(grid[0])
    seen=[[False]*W for _ in range(H)]
    comps=[]
    for i in range(H):
        for j in range(W):
            if grid[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and not seen[nx][ny] and grid[nx][ny]!=bg:
                            seen[nx][ny]=True; st.append((nx,ny))
                comps.append(cells)
    comps.sort(key=lambda c:min(y for x,y in c))
    c=comps[0]
    r0=min(x for x,y in c); r1=max(x for x,y in c)
    c0=min(y for x,y in c); c1=max(y for x,y in c)
    return [[grid[r][cc] for cc in range(c0,c1+1)] for r in range(r0,r1+1)]

